insert into public.artworks (title, slug, category, medium, size, year, description, image_url, image_alt, object_position, is_available, is_featured, show_on_home, display_order) values ('Sharing Truth No Other Way', 'sharing-truth-no-other-way', 'spiritual', 'Oil on Canvas', '24" x 30"', 2025, 'With one bite of the fruit Eve gave the world the ability to decipher good from evil.', '/artwork/sharing-truth-no-other-way.jpg', 'Sharing Truth No Other Way — original painting by Ella Wright', 'center center', false, false, false, 2);
