insert into public.artworks (title, slug, category, medium, size, year, description, image_url, image_alt, object_position, is_available, is_featured, show_on_home, display_order) values ('Brother of Jared', 'brother-of-jared', 'spiritual', 'Oil on Canvas', '24" x 30"', 2024, '', '/artwork/brother-of-jared.jpg', 'Brother of Jared — original painting by Ella Wright', 'center 32%', false, false, false, 4);
insert into public.artworks (title, slug, category, medium, size, year, description, image_url, image_alt, object_position, is_available, is_featured, show_on_home, display_order) values ('Supported on all Sides', 'supported-on-all-sides', 'spiritual', 'Oil on Canvas', '24" x 30"', 2024, 'We are never alone throughout our successes, challenges, and mistakes. We have an infinite cheering squad in the angels around us and receive loving support from our Heavenly Parents as well as our loved ones on earth.', '/artwork/supported-on-all-sides.jpg', 'Supported on all Sides — original painting by Ella Wright', 'center center', false, false, false, 5);
insert into public.artworks (title, slug, category, medium, size, year, description, image_url, image_alt, object_position, is_available, is_featured, show_on_home, display_order) values ('Yearn to Learn', 'yearn-to-learn', 'spiritual', 'Oil on Canvas', '24" x 30"', 2024, 'I painted this after finishing a research paper on the effects of controversial literature. The figures made from the book pages represent empathy, culture, exploration, diversity, discovery, and critical thinking. Reading can be a powerful source of learning to understand the perspectives of the people living beside us.', '/artwork/yearn-to-learn.jpg', 'Yearn to Learn — original painting by Ella Wright', 'center center', false, false, false, 6);
insert into public.artworks (title, slug, category, medium, size, year, description, image_url, image_alt, object_position, is_available, is_featured, show_on_home, display_order) values ('Benefactor of Pioneer Greatness', 'benefactor-of-pioneer-greatness', 'women-motherhood', 'Oil on Canvas', '24" x 30"', 2023, 'My great grandmother always said, “You come from pioneer stock!” And she passed that down to her daughter and now my mom says it to me. I come from a heritage of strong women. This piece embodies the greatness we pass from one generation to another. My heritage includes a strong 52 year old woman who left Europe, traveled thousands of miles on foot on her own, and built a new world for her family. I am a part of that new world, full of opportunities and privilege as a result of her strength.', '/artwork/benefactor-of-pioneer-greatness.jpg', 'Benefactor of Pioneer Greatness — original painting by Ella Wright', 'center center', false, false, false, 7);
insert into public.artworks (title, slug, category, medium, size, year, description, image_url, image_alt, object_position, is_available, is_featured, show_on_home, display_order) values ('Heavenly Hands', 'heavenly-hands', 'spiritual', 'Oil on Canvas', '24" x 30"', 2024, 'Heavenly Hands is a celebration of the divine within womanhood—the sacredness of nurturing life, the quiet strength found in surrender, and the beauty that blossoms in love.
insert into public.artworks (title, slug, category, medium, size, year, description, image_url, image_alt, object_position, is_available, is_featured, show_on_home, display_order) values ('Hello There', 'hello-there', 'spiritual', 'Oil on Canvas', '24" x 30"', 2023, '', '/artwork/hello-there.jpg', 'Hello There — original painting by Ella Wright', 'center 30%', false, false, false, 9);
insert into public.artworks (title, slug, category, medium, size, year, description, image_url, image_alt, object_position, is_available, is_featured, show_on_home, display_order) values ('Making Waves', 'making-waves', 'landscapes', 'Oil on Canvas', '24" x 30"', 2023, '', '/artwork/making-waves.jpg', 'Making Waves — original painting by Ella Wright', 'center center', false, false, false, 10);
insert into public.artworks (title, slug, category, medium, size, year, description, image_url, image_alt, object_position, is_available, is_featured, show_on_home, display_order) values ('Perspective', 'perspective', 'landscapes', 'Oil on Canvas', '24" x 30"', 2023, 'We each bring our own perspectives, gifts, and color into the world. There is a reason we do not see in black and white. Connecting with each other brings beauty and strength.', '/artwork/perspective.jpg', 'Perspective — original painting by Ella Wright', 'center 35%', false, false, false, 11);
