insert into public.artworks (title, slug, category, medium, size, year, description, image_url, image_alt, object_position, is_available, is_featured, show_on_home, display_order) values ('Creation', 'creation', 'spiritual', 'Oil on Canvas', '24" x 30"', 2022, 'I like to think that we helped God during the creation. This digital artwork shows a pre-mortal spirit watching and helping as God sculpts her face.', '/artwork/creation.jpg', 'Creation — original painting by Ella Wright', 'center center', false, false, false, 17);
