insert into public.artworks (title, slug, category, medium, size, year, description, image_url, image_alt, object_position, is_available, is_featured, show_on_home, display_order) values ('House of the Lord', 'house-of-the-lord', 'spiritual', 'Oil on Canvas', '24" x 30"', 2022, 'Inspired by President Thomas S. Monson''s promise: "I know your lives are busy. I know that you have much to do. But I make you a promise that if you will go to the house of the Lord, you will be blessed; life will be better for you."', '/artwork/house-of-the-lord.jpg', 'House of the Lord — original painting by Ella Wright', 'center 20%', false, false, false, 24);
