insert into public.artworks (title, slug, category, medium, size, year, description, image_url, image_alt, object_position, is_available, is_featured, show_on_home, display_order) values ('The Service Quilt', 'the-service-quilt', 'women-motherhood', 'Oil on Canvas', '24" x 30"', 2022, 'This painting shows an older woman teaching a girl to sew. Each pattern block represents a different way to serve others. In my life I have been taught by my parents, grandparents, teachers, and youth leaders how to serve and the joy it brings.', '/artwork/the-service-quilt.jpg', 'The Service Quilt — original painting by Ella Wright', 'center center', false, false, false, 32);
insert into public.artworks (title, slug, category, medium, size, year, description, image_url, image_alt, object_position, is_available, is_featured, show_on_home, display_order) values ('Trying To Be Like Him', 'trying-to-be-like-him', 'spiritual', 'Oil on Canvas', '24" x 30"', 2022, 'The animals following Jesus represent his traits. The little boy is working hard to imitate these.', '/artwork/trying-to-be-like-him.jpg', 'Trying To Be Like Him — original painting by Ella Wright', 'center center', false, false, false, 33);
insert into public.artworks (title, slug, category, medium, size, year, description, image_url, image_alt, object_position, is_available, is_featured, show_on_home, display_order) values ('You Are Not Alone', 'you-are-not-alone', 'spiritual', 'Oil on Canvas', '24" x 30"', 2022, 'He opened his call to discover where he would be assigned to serve a two year religious mission. He’s assigned to the same mission as his grandpa who passed before he was born. How ever present God’s hand is in the details of our lives. We are not alone.', '/artwork/you-are-not-alone.jpg', 'You Are Not Alone — original painting by Ella Wright', 'center center', false, false, false, 34);
